def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    sep_color = grid[sep_rows[0]][0] if sep_rows else grid[0][sep_cols[0]]

    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    background = max(set(v for row in grid for v in row),
                     key=lambda v: sum(row.count(v) for row in grid))
    return [
        [
            1 if sum(grid[r][c] != background and grid[r][c] != sep_color
                     for r in range(r0, r1)
                     for c in range(c0, c1)) == 2 else background
            for c0, c1 in col_ranges
        ]
        for r0, r1 in row_ranges
    ]
